    StatusEvents* m_statusEvents = nullptr;
    winrt::com_ptr<IAudioEndpointVolume> m_watchedVolume;
    DWORD m_networkCookie = 0;
    winrt::com_ptr<IConnectionPoint> m_networkPoint;
    bool m_wlanWatched = false;
